do $install$ declare article text := (select substring(s.content->>'passage' from position('THE PASSAGE: ' in s.content->>'passage')) from private.ielts_learning_tasks s where s.code='bh-ielts-targeted-reading-r29-v2' and s.content_sha256='6bb73ed1caf02b82aaa4895675e397b547f9647b7177cee6a1e362901c9f4cb8');
begin
 if article is null or length(article) < 3000 then raise exception 'targeted_reading_06_passage_missing'; end if;
 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r30-v2','0.2.0','Lesson 6 step 3 of 6: Two paragraphs, one trap','reading','guided_practice','Read LEARN FIRST and the worked example. Then choose the paragraph that contains the information. NB The same letter can be the answer more than once.','A word you recognise is a warning, not an answer. Choose the paragraph that has the meaning.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Which paragraph contains an account of how conditions after dark may weaken people''s capacity to cope with heat?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q2", "prompt": "Which paragraph contains an example of a way of coping with heat that makes the original problem worse?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}]}, {"id": "q3", "prompt": "Which paragraph contains a caution against drawing wide conclusions from evidence collected at one location?", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}, {"id": "q4", "prompt": "Which paragraph contains a reference to the justification some local authorities give for offering financial help?", "accepted_answers": ["E"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q5", "prompt": "Which paragraph contains mention of an option suited to buildings unable to carry a planted roof?", "accepted_answers": ["F"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "D", "label": "Paragraph D"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q6", "prompt": "Which paragraph contains a description of how plants carry heat away from a roof?", "accepted_answers": ["C"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 B: \"bodies deprived of the chance to cool down overnight are less able to withstand the following day''s heat\". Trap A: it mentions after dusk, but only temperatures.\n2 B: air conditioners'' waste heat \"intensifies the very problem they were bought to solve\". Trap A: it lists air-conditioning units only as a source of heat. B is used twice.\n3 C: \"readings taken on a single rooftop reveal little about conditions in the surrounding district\". Trap D: it limits the benefits but says nothing about evidence.\n4 E: \"reasoning that vegetated roofs retain rainfall that would otherwise overwhelm the sewers\". ''Reasoning that'' introduces the justification. Trap F: it mentions grants but criticises them.\n5 F: cool roofs \"are far cheaper on buildings whose structure cannot support soil\". Trap D: it names the problem buildings but gives no option.\n6 C: \"moisture drawn up through the roots evaporates from the leaves, carrying energy away with it\". Trap D: it mentions plants but is about wildlife and weight.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Locate specific detail when a nearby paragraph shares the topic or key words (matching information)."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: choose by meaning, not by a word you recognise

In each question, one paragraph shares a word or topic with the question (the trap). The other one has the meaning.

WORKED EXAMPLE
Question: "a reason why some planted roofs do little for wildlife". Paragraph C or D?
1. Kind: a reason why. Topic: wildlife.
2. C has the echo word "vegetation" and explains how plants cool roofs. No wildlife.  -> trap
3. D: "the thin mats of drought-tolerant sedum ... sustain only a fraction of the insect and bird life". Insects and birds = wildlife; thin mats = the reason.  -> answer D
Rule: a word you recognise is a warning, not an answer.
NB The same letter can be the answer more than once.' || '

- - - - - - - - - - - - - - - - - - - -

' || article)),'{"author": "Brains Heist AI-assisted original", "rights": "Original Brains Heist text; no third-party passages or questions copied.", "bible": "2.0.0", "human_review": "pending", "difficulty_comparability": "Not calibrated equivalent forms; no bands. Change is judged only by bh-practice-effect-v1 (provisional).", "source": "docs/ielts/practice/TARGETED_READING_06.json 0.2.0"}'::jsonb,'37d6d965041b896ef22f3633b3b9a55a60b4930581759291aeae6347285a6da9',true) on conflict (code) do nothing;
